def solve_cvrp(instance):
    depot = instance["depot_index"]
    customers = list(instance["customer_ids"])
    demands = instance["demands"]
    capacity = instance["capacity"]
    matrix = instance["distance_matrix"]

    if not customers:
        return []

    def route_cost(route):
        if not route:
            return 0
        c = matrix[depot][route[0]] + matrix[route[-1]][depot]
        for i in range(len(route) - 1):
            c += matrix[route[i]][route[i + 1]]
        return c

    def route_load(route):
        s = 0
        for v in route:
            s += demands[v]
        return s

    def build_clarke_wright():
        routes = [[c] for c in customers]
        loads = [demands[c] for c in customers]

        # route_of: node -> route index
        route_of = {}
        for rid, r in enumerate(routes):
            for v in r:
                route_of[v] = rid

        savings = []
        # deterministic ordering for equal savings
        for i_idx in range(len(customers)):
            i = customers[i_idx]
            di = matrix[depot][i]
            for j_idx in range(i_idx + 1, len(customers)):
                j = customers[j_idx]
                s = di + matrix[depot][j] - matrix[i][j]
                savings.append((s, i, j))
        savings.sort(key=lambda x: (-x[0], x[1], x[2]))

        def can_merge(load_a, load_b):
            return load_a + load_b <= capacity

        for s, i, j in savings:
            ri = route_of.get(i, None)
            rj = route_of.get(j, None)
            if ri is None or rj is None or ri == rj:
                continue
            ra = routes[ri]
            rb = routes[rj]
            if not ra or not rb:
                continue
            if not can_merge(loads[ri], loads[rj]):
                continue

            i_front, i_back = ra[0], ra[-1]
            j_front, j_back = rb[0], rb[-1]

            # Merge only if endpoints match to avoid creating internal breaks
            merged = None
            if i_back == i and j_front == j:
                merged = ra + rb
            elif i_back == i and j_back == j:
                merged = ra + rb[::-1]
            elif i_front == i and j_front == j:
                merged = ra[::-1] + rb
            elif i_front == i and j_back == j:
                merged = ra[::-1] + rb[::-1]

            if merged is None:
                continue

            routes[ri] = merged
            loads[ri] += loads[rj]
            routes[rj] = []
            # update route_of for nodes in rj
            for v in rb:
                route_of[v] = ri

        return [r for r in routes if r]

    def apply_improvement(routes):
        routes = [r[:] for r in routes if r]
        if not routes:
            return []

        R = len(routes)
        loads = [route_load(r) for r in routes]
        costs = [route_cost(r) for r in routes]

        def recompute_all():
            nonlocal loads, costs
            loads = [route_load(r) for r in routes]
            costs = [route_cost(r) for r in routes]

        # Intra-route 2-opt
        def try_intra_2opt(max_passes=2):
            nonlocal costs
            for _ in range(max_passes):
                improved = False
                for rid in range(len(routes)):
                    r = routes[rid]
                    m = len(r)
                    if m < 4:
                        continue
                    base = costs[rid]
                    # i is start index of the first edge, k is end index of second edge
                    for i in range(m - 1):
                        a = depot if i == 0 else r[i - 1]
                        b = r[i]
                        for k in range(i + 1, m):
                            c = r[k]
                            d = depot if k == m - 1 else r[k + 1]
                            delta = -matrix[a][b] - matrix[c][d] + matrix[a][c] + matrix[b][d]
                            if delta < -1e-12:
                                new_r = r[:i] + r[i:k + 1][::-1] + r[k + 1:]
                                routes[rid] = new_r
                                costs[rid] = base + delta
                                improved = True
                                break
                        if improved:
                            break
                    if improved:
                        break
                if not improved:
                    break

        # Inter-route relocate (move one customer from route A to best position in route B)
        def try_relocate(max_passes=3):
            nonlocal costs, loads
            for _ in range(max_passes):
                improved = False
                # iterate deterministic order
                for a in range(len(routes)):
                    ra = routes[a]
                    if not ra:
                        continue
                    for idx in range(len(ra)):
                        node = ra[idx]
                        if loads[a] - demands[node] < 0:
                            continue

                        # remove node from a
                        left = depot if idx == 0 else ra[idx - 1]
                        right = depot if idx == len(ra) - 1 else ra[idx + 1]
                        base_cost_a = costs[a]
                        rem_delta_a = -matrix[left][node] - matrix[node][right] + matrix[left][right]
                        new_cost_a = base_cost_a + rem_delta_a
                        new_ra = ra[:idx] + ra[idx + 1:]

                        if not new_ra:
                            # allow empty route removal later, but keep delta logic
                            pass

                        # try insert into some b
                        for b in range(len(routes)):
                            if b == a:
                                continue
                            rb = routes[b]
                            if rb is None:
                                continue
                            if not rb and loads[b] != 0:
                                continue
                            if loads[b] + demands[node] > capacity:
                                continue

                            base_cost_b = costs[b]
                            # choose best insertion position p in [0..len(rb)]
                            best_total_delta = None
                            best_p = None

                            Lrb = len(rb)
                            for p in range(Lrb + 1):
                                ins_left = depot if p == 0 else rb[p - 1]
                                ins_right = depot if p == Lrb else rb[p]
                                ins_delta_b = -matrix[ins_left][ins_right] + matrix[ins_left][node] + matrix[node][ins_right]
                                total_delta = (new_cost_a + (base_cost_b + ins_delta_b)) - (base_cost_a + base_cost_b)
                                if best_total_delta is None or total_delta < best_total_delta - 1e-12 or (
                                    abs(total_delta - best_total_delta) <= 1e-12 and p < best_p
                                ):
                                    best_total_delta = total_delta
                                    best_p = p

                            if best_total_delta is not None and best_total_delta < -1e-12:
                                # apply move
                                new_rb = rb[:best_p] + [node] + rb[best_p:]
                                routes[a] = new_ra
                                routes[b] = new_rb
                                loads[a] -= demands[node]
                                loads[b] += demands[node]
                                costs[a] = route_cost(new_ra)
                                costs[b] = route_cost(new_rb)
                                improved = True
                                break
                        if improved:
                            break
                    if improved:
                        break
                if not improved:
                    break

        # Inter-route swap one customer between routes
        def try_inter_swap(max_checks=800):
            nonlocal loads, costs
            checks = 0
            # deterministic nested loops; stop after enough improvements or checks
            while checks < max_checks:
                improved = False
                for a in range(len(routes)):
                    ra = routes[a]
                    if not ra:
                        continue
                    for b in range(len(routes)):
                        if b == a:
                            continue
                        rb = routes[b]
                        if not rb:
                            continue
                        base_cost_a = costs[a]
                        base_cost_b = costs[b]
                        for ia in range(len(ra)):
                            na = ra[ia]
                            for ib in range(len(rb)):
                                nb = rb[ib]
                                if loads[a] - demands[na] + demands[nb] > capacity:
                                    continue
                                if loads[b] - demands[nb] + demands[na] > capacity:
                                    continue

                                # recompute using full costs (still deterministic, simpler and safe)
                                new_ra = ra[:]
                                new_rb = rb[:]
                                new_ra[ia] = nb
                                new_rb[ib] = na
                                ca = route_cost(new_ra)
                                cb = route_cost(new_rb)
                                if (ca + cb) < (base_cost_a + base_cost_b) - 1e-12:
                                    routes[a] = new_ra
                                    routes[b] = new_rb
                                    loads[a] = loads[a] - demands[na] + demands[nb]
                                    loads[b] = loads[b] - demands[nb] + demands[na]
                                    costs[a] = ca
                                    costs[b] = cb
                                    improved = True
                                    checks += 1
                                    break
                            if improved:
                                break
                        if improved:
                            break
                    if improved:
                        break
                if not improved:
                    break

        # Run improvements
        try_relocate(max_passes=3)
        try_intra_2opt(max_passes=2)
        try_inter_swap(max_checks=800)

        routes = [r for r in routes if r]
        return routes

    # Fallback: nearest-chain insertion
    def build_nearest_chain():
        # Deterministic ordering: sort by (demand desc, id asc)
        ordered = sorted(customers, key=lambda x: (-demands[x], x))
        # Precompute deterministic candidate neighbors list by distance
        cand_by = {}
